// Measure the production stream window with the complete installed ecology.
// Checksums cover the generated bytes; cache wins must never alter the world.
import assert from "node:assert/strict";
import {performance} from "node:perf_hooks";
import {builtinContentCatalog} from "@openvoxel/content";
import {baseBlockCatalogSource, createWorldBlockRegistry} from "@openvoxel/blocks";
import {createWorldGeneratorRegistry, instantiateWorldGenerator, defaultGenerator} from "@openvoxel/world-generation";
import {streamedChunkPositions} from "../dist/runtime/render-window.js";

const selected = builtinContentCatalog.defaultContent();
const blocks = createWorldBlockRegistry(baseBlockCatalogSource, selected.blockContributions);
const definitions = createWorldGeneratorRegistry(undefined, selected.generatorContributions, selected.ecosystemPacks);
const generator = instantiateWorldGenerator(defaultGenerator, "continental-ridges", 16, blocks, definitions);
const radius = Number(process.argv[2] ?? 8);
assert.ok(Number.isInteger(radius) && radius >= 3 && radius <= 8);
let tracked = [];
const key = position => `${position.x}:${position.y}:${position.z}`;
const windows = [
  ["initial", {x: -48, y: 5, z: 16}, -1],
  ["move", {x: -48, y: 5, z: 14}, -1],
  ["turn", {x: -48, y: 5, z: 14}, 1],
];
for (const [label, center, forwardZ] of windows) {
  const desired = streamedChunkPositions({center, forwardX: 0, forwardY: 0, forwardZ, minimap: true, radius}, 0, 15, tracked);
  const resident = new Set(tracked.map(key));
  const missing = desired.filter(position => !resident.has(key(position)));
  const times = [];
  let checksum = 2166136261;
  let elapsedMs = 0;
  for (const position of missing) {
    const started = performance.now();
    const chunk = generator.generate(position);
    const elapsed = performance.now() - started;
    elapsedMs += elapsed;
    times.push(elapsed);
    for (const index of chunk.indices) checksum = Math.imul(checksum ^ chunk.palette[index], 16777619) >>> 0;
  }
  times.sort((a, b) => a - b);
  console.log(JSON.stringify({
    label, radius, chunks: missing.length, columns: new Set(missing.map(position => `${position.x}:${position.z}`)).size,
    elapsedMs: Math.round(elapsedMs), meanMs: elapsedMs / missing.length,
    p95Ms: times[Math.floor(times.length * .95)] ?? 0, checksum,
  }));
  tracked = desired;
}
